#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, "..");

function help() {
  console.log(`Usage:
  node scripts/submit-recursive-bundle.mjs <target> --bundle <file.json> --address <0x...> [options]

Targets:
  governance   -> POST /api/governance/eligibility (attestFsftForVoting)
  rewards      -> POST /api/rewards/attest

Options:
  --bundle <path>         Bundle JSON generated by generate-recursive-proof-bundle.mjs
  --address <0x...>       Must match selected account address in local wallet
  --account-index <n>     Defaults to 0
  --base-url <url>        Defaults to http://localhost:3000
  --dry-run <true|false>  Print payload only, no request
`);
}

function parseArgs(argv) {
  if (argv.length === 0 || argv[0] === "-h" || argv[0] === "--help") {
    return { help: true };
  }

  const target = argv[0];
  const args = {};
  const rest = argv.slice(1);

  while (rest.length > 0) {
    const key = rest.shift();
    if (!key || !key.startsWith("--")) {
      throw new Error(`Unexpected token: ${key}`);
    }
    const value = rest.shift();
    if (!value || value.startsWith("--")) {
      throw new Error(`Missing value for ${key}`);
    }
    const normalized = key.slice(2).replace(/-([a-z])/g, (_, c) => c.toUpperCase());
    args[normalized] = value;
  }

  return { target, args };
}

function requireArg(args, name) {
  const value = args[name];
  if (!value) {
    throw new Error(`Missing required --${name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}`);
  }
  return value;
}

async function main() {
  const parsed = parseArgs(process.argv.slice(2));
  if (parsed.help) {
    help();
    process.exit(0);
  }

  const { target, args } = parsed;
  const bundlePath = path.resolve(ROOT, requireArg(args, "bundle"));
  const address = requireArg(args, "address");
  const accountIndex = Number(args.accountIndex ?? "0");
  const baseUrl = args.baseUrl ?? "http://localhost:3000";
  const dryRun = (args.dryRun ?? "false").toLowerCase() === "true";

  const bundle = JSON.parse(fs.readFileSync(bundlePath, "utf8"));
  const recursiveProof = bundle?.recursiveProof ?? bundle;

  if (!recursiveProof || !Array.isArray(recursiveProof.verificationKey) || !Array.isArray(recursiveProof.proof)) {
    throw new Error("Bundle JSON must contain recursiveProof.verificationKey[] and recursiveProof.proof[]");
  }

  let endpoint = "";
  let body = {};

  if (target === "governance") {
    endpoint = "/api/governance/eligibility";
    body = {
      action: "attestFsftForVoting",
      address,
      accountIndex,
      recursiveProof,
    };
  } else if (target === "rewards") {
    endpoint = "/api/rewards/attest";
    body = {
      address,
      accountIndex,
      recursiveProof,
    };
  } else {
    throw new Error(`Unknown target: ${target}`);
  }

  if (dryRun) {
    console.log(JSON.stringify({ url: `${baseUrl}${endpoint}`, body }, null, 2));
    return;
  }

  const res = await fetch(`${baseUrl}${endpoint}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  const data = await res.json().catch(() => ({}));
  console.log(`HTTP ${res.status}`);
  console.log(JSON.stringify(data, null, 2));

  if (!res.ok) {
    process.exit(1);
  }
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
